#!/usr/bin/env python3
"""Extended real E2E using the existing QA tenant and cleanup contract."""
from pathlib import Path
base=Path("/root/BORIS/frontend/scripts/qa-messenger-v70-multiuser.py")
source=base.read_text()
marker="      # Viewer: read-only in UI and backend"
assert source.count(marker)==1
extra="\n      # Extended acceptance uses the same two real contexts and dedicated QA tenant.\n      def http(uid,method,path,body=None):\n          r=requests.request(method,WEB+\"/api/internal-messenger\"+path,headers={\"Authorization\":\"Bearer \"+tokens[uid]},json=body,timeout=20)\n          if r.status_code >=400: raise RuntimeError(method+\" \"+path+\" status=\"+str(r.status_code))\n          return r.json()\n      def check(name,ok,details=None):\n          results[name]={\"ok\":bool(ok),\"details\":details}\n          if not ok: failures.append(name)\n      owner.goto(WEB+f\"/messenger?account_id={ACCOUNT}&internal_conversation_id={group_id}\",wait_until=\"domcontentloaded\")\n      emp.goto(WEB+f\"/messenger?account_id={ACCOUNT}&internal_conversation_id={group_id}\",wait_until=\"domcontentloaded\")\n      owner.wait_for_timeout(2000); emp.wait_for_timeout(2000)\n      text0=PREFIX+\" FEATURE\"\n      send(owner,text0)\n      emp.get_by_text(text0,exact=True).wait_for(timeout=12000)\n      msgid=int(dbrow(\"SELECT id FROM internal_messages WHERE conversation_id=:c AND body=:b\",{\"c\":group_id,\"b\":text0})[\"id\"])\n      bubble=owner.locator(\"#internal-message-\"+str(msgid))\n      bubble.hover();bubble.get_by_role(\"button\",name=\"Изменить\",exact=True).click()\n      composer(owner).locator(\"textarea\").fill(text0+\" EDITED\")\n      composer(owner).get_by_role(\"button\",name=\"Сохранить\",exact=True).click()\n      emp.get_by_text(text0+\" EDITED\",exact=True).wait_for(timeout=12000);check(\"EDIT_REALTIME\",True)\n      bubble.hover();bubble.get_by_role(\"button\",name=\"Ответить\",exact=True).click()\n      send(owner,PREFIX+\" REPLY\")\n      emp.get_by_text(PREFIX+\" REPLY\",exact=True).wait_for(timeout=12000)\n      check(\"REPLY_REALTIME\",dbrow(\"SELECT reply_to_message_id FROM internal_messages WHERE conversation_id=:c AND body=:b\",{\"c\":group_id,\"b\":PREFIX+\" REPLY\"})[\"reply_to_message_id\"]==msgid)\n      for emoji in [\"👍\",\"✅\",\"❤️\",\"😂\"]:\n          bubble.hover();bubble.get_by_role(\"button\",name=re.compile(\"😊\")).click()\n          bubble.get_by_role(\"button\",name=emoji,exact=True).click()\n          emp.wait_for_timeout(900)\n      data=http(EMPLOYEE_ID,\"GET\",f\"/conversations/{group_id}/messages\")[\"messages\"]\n      m=next(x for x in data if x[\"id\"]==msgid)\n      check(\"REACTIONS\",set(x[\"reaction\"] for x in m[\"reactions\"])=={\"👍\",\"✅\",\"❤️\",\"😂\"})\n      bubble.hover();bubble.get_by_role(\"button\",name=\"Закрепить\",exact=True).click()\n      emp.locator('[class*=\"pinnedStrip\"]').get_by_text(text0+\" EDITED\",exact=True).wait_for(timeout=12000);check(\"PIN_REALTIME\",True)\n      bubble.hover();bubble.get_by_role(\"button\",name=\"Открепить\",exact=True).click()\n      emp.locator('[class*=\"pinnedStrip\"]').wait_for(state=\"hidden\",timeout=12000);check(\"UNPIN_REALTIME\",True)\n      owner.once(\"dialog\",lambda d:d.accept())\n      bubble.hover();bubble.get_by_role(\"button\",name=\"Удалить\",exact=True).click()\n      emp.locator(\"#internal-message-\"+str(msgid)).get_by_text(\"Сообщение удалено\",exact=True).wait_for(timeout=12000);check(\"DELETE_REALTIME\",True)\n      contexts[EMPLOYEE_ID].set_offline(True)\n      emp.get_by_text(\"Нет связи\",exact=True).first.wait_for(timeout=10000);check(\"OFFLINE_STATUS\",True)\n      missed=[PREFIX+\" MISSED \"+str(i) for i in range(5)]\n      for msg in missed:send(owner,msg)\n      contexts[EMPLOYEE_ID].set_offline(False)\n      emp.get_by_text(\"Онлайн\",exact=True).first.wait_for(timeout=20000)\n      for msg in missed:emp.get_by_text(msg,exact=True).wait_for(timeout=15000)\n      seen=emp.locator('[class*=\"internalHistory\"] p').all_text_contents()\n      check(\"MISSED_EVENTS_ORDER_DEDUP\",[x for x in seen if x in missed]==missed)\n      repeat=http(OWNER_ID,\"POST\",\"/conversations\",{\"account_id\":ACCOUNT,\"kind\":\"DM\",\"member_user_ids\":[EMPLOYEE_ID]})\n      check(\"DM_DEDUP\",repeat[\"conversation_id\"]==dm_id)\n      # HTTP group lifecycle uses real canonical mutations.\n      http(OWNER_ID,\"POST\",f\"/conversations/{group_id}/members\",{\"user_id\":VIEWER_ID})\n      check(\"GROUP_ADD_MEMBER\",any(x[\"user_id\"]==VIEWER_ID for x in http(OWNER_ID,\"GET\",f\"/conversations/{group_id}/members\")[\"members\"]))\n      http(OWNER_ID,\"DELETE\",f\"/conversations/{group_id}/members/{VIEWER_ID}\")\n      denied=requests.get(WEB+f\"/api/internal-messenger/conversations/{group_id}/messages\",headers={\"Authorization\":\"Bearer \"+tokens[VIEWER_ID]},timeout=10)\n      check(\"GROUP_REMOVE_ACCESS\",denied.status_code in (403,404),denied.status_code)\n      http(OWNER_ID,\"PATCH\",f\"/conversations/{group_id}\",{\"title\":GROUP_TITLE+\" renamed\"})\n      emp.get_by_role(\"heading\",name=GROUP_TITLE+\" renamed\",exact=True).wait_for(timeout=12000);check(\"GROUP_RENAME_REALTIME\",True)\n      for role in [\"ADMIN\",\"MEMBER\"]:\n          http(OWNER_ID,\"PATCH\",f\"/conversations/{group_id}/members/{EMPLOYEE_ID}\",{\"role\":role})\n          check(\"GROUP_\"+role,any(x[\"user_id\"]==EMPLOYEE_ID and x[\"role\"]==role for x in http(OWNER_ID,\"GET\",f\"/conversations/{group_id}/members\")[\"members\"]))\n      http(OWNER_ID,\"POST\",f\"/conversations/{group_id}/transfer-ownership\",{\"new_owner_user_id\":EMPLOYEE_ID})\n      check(\"GROUP_TRANSFER_OWNER\",any(x[\"user_id\"]==EMPLOYEE_ID and x[\"role\"]==\"OWNER\" for x in http(EMPLOYEE_ID,\"GET\",f\"/conversations/{group_id}/members\")[\"members\"]))\n      http(OWNER_ID,\"POST\",f\"/conversations/{group_id}/leave\")\n      check(\"GROUP_LEAVE\",all(x[\"user_id\"]!=OWNER_ID for x in http(EMPLOYEE_ID,\"GET\",f\"/conversations/{group_id}/members\")[\"members\"]))\n      http(EMPLOYEE_ID,\"PATCH\",f\"/conversations/{group_id}\",{\"title\":GROUP_TITLE})\n"
extra=extra.replace('      bubble.hover();bubble.get_by_role("button",name="Изменить",exact=True).click()', '      bubble.hover()\\n      print("FEATURE_DIAG",json.dumps({"buttons":bubble.locator("button").all_text_contents(),"aria":bubble.aria_snapshot(),"api":next(({"id":x["id"],"is_own":x.get("is_own"),"sender_user_id":x.get("sender_user_id")} for x in http(OWNER_ID,"GET",f"/conversations/{group_id}/messages")["messages"] if x["id"]==msgid),{})},ensure_ascii=False),flush=True)\\n      bubble.get_by_role("button",name="Изменить",exact=True).click()' .replace("\\\\n","\\n"))
extra=extra.replace("\\n", "\n")
for label in ("Изменить","Ответить","Закрепить","Открепить","Удалить"):
    extra=extra.replace('name="'+label+'",exact=True', 'name=re.compile("^'+label+'(?:\\\\s|$)")')
source=source.replace(marker,extra+"\n"+marker)
source=source.replace('finally:\n    for uid,sid in sessions:', 'except Exception as exc:\n    failures.append(type(exc).__name__+":"+str(exc))\nfinally:\n    for uid,sid in sessions:')
exec(compile(source,str(base),"exec"))
